    /// <summary>Řádek tabulky činností: kód, název, rozsah, sazba, cena bez DPH, DPH, s DPH.</summary>
    public readonly record struct RadekCinnosti(
        string Kod, string Nazev, string Rozsah, string Sazba, string BezDph, string Dph, string SDph);

    /// <summary>Řádek tabulky licencí: kód, název, cena bez DPH, DPH, s DPH (POL a PPOL zůstávají prázdné).</summary>
    public readonly record struct RadekLicence(string Kod, string Nazev, string BezDph, string Dph, string SDph);

    /// <summary>Řádek rekapitulace: pořadí ze sekce 1, název požadavku, cena.</summary>
    public readonly record struct RadekRekapitulace(string Poradi, string Nazev, string Cena);

    /// <summary>Součty pod tabulkou: bez DPH, DPH, s DPH.</summary>
    public readonly record struct Soucty(string BezDph, string Dph, string SDph);

    /// <summary>Sekce 1 — přehled požadavků (Poř. č., Č. úkolu VP, Název požadavku, Č. HTL).</summary>
    public static Table TabulkaPredmetu(IEnumerable<(string Poradi, string CisloUkolu, string Nazev, string Htl)> pozadavky)
        => Tabulka(Predmet_TblPr, Predmet_Sloupce,
            pozadavky.Select(p => Vypln(Predmet_Radek, p.Poradi, p.CisloUkolu, p.Nazev, p.Htl)).Prepend(Predmet_Hlavicka));

    /// <summary>Sekce 2 — individuální úpravy (činnosti A–D) s řádkem CELKEM.</summary>
    public static Table TabulkaCinnosti(IEnumerable<RadekCinnosti> radky, Soucty soucty)
        => Tabulka(Cinnosti_TblPr, Cinnosti_Sloupce, radky
            .Select(r => Vypln(Cinnosti_Radek, r.Kod, r.Nazev, r.Rozsah, r.Sazba, r.BezDph, r.Dph, r.SDph))
            .Prepend(Cinnosti_Hlavicka)
            .Append(Vypln(Cinnosti_Celkem, "CELKEM", soucty.BezDph, soucty.Dph, soucty.SDph)));

    /// <summary>Sekce 2 — licenční rozšíření; POL a PPOL doplňuje uživatel (spec B5).</summary>
    public static Table TabulkaLicenci(IEnumerable<RadekLicence> radky, Soucty soucty)
        => Tabulka(Licence_TblPr, Licence_Sloupce, radky
            .Select(r => Vypln(Licence_Radek, r.Kod, r.Nazev, string.Empty, string.Empty, r.BezDph, r.Dph, r.SDph))
            .Prepend(Licence_Hlavicka)
            .Append(Vypln(Licence_Celkem, "CELKEM licenční rozšíření", soucty.BezDph, soucty.Dph, soucty.SDph)));

    /// <summary>
    /// Sekce 3 — rekapitulace individuálních úprav (<paramref name="licence"/> = false) nebo
    /// licencí: požadavky, prázdný řádek, součty „Celkem | bez DPH“, „DPH … %“, „s DPH“.
    /// </summary>
    public static Table Rekapitulace(bool licence, IEnumerable<RadekRekapitulace> radky, Soucty soucty, string dphPopisek)
    {
        var (tblPr, sloupce, hlavicka, radek, prazdny, celkem, dph, sDph) = licence
            ? (RekapLicence_TblPr, RekapLicence_Sloupce, RekapLicence_Hlavicka, RekapLicence_Radek,
                RekapLicence_Prazdny, RekapLicence_Celkem, RekapLicence_Dph, RekapLicence_SDph)
            : (Rekap_TblPr, Rekap_Sloupce, Rekap_Hlavicka, Rekap_Radek,
                Rekap_Prazdny, Rekap_Celkem, Rekap_Dph, Rekap_SDph);

        return Tabulka(tblPr, sloupce, radky
            .Select(r => Vypln(radek, r.Poradi, r.Nazev, r.Cena))
            .Prepend(hlavicka)
            .Append(prazdny)
            .Append(Vypln(celkem, "Celkem", "bez DPH", soucty.BezDph))
            .Append(Vypln(dph, string.Empty, dphPopisek, soucty.Dph))
            .Append(Vypln(sDph, string.Empty, "s DPH", soucty.SDph)));
    }

    /// <summary>Sekce 3 — souhrn: úprava APV a DZ, licenční rozšíření, CELKEM. Sazbu DPH nese záhlaví.</summary>
    public static Table Souhrn(Soucty upravy, Soucty licence, Soucty celkem, string dphProcenta)
        => Tabulka(Souhrn_TblPr, Souhrn_Sloupce, new[]
        {
            Vypln(Souhrn_Hlavicka, dphProcenta),
            Vypln(Souhrn_Uprava, "Úprava APV a DZ celkem", upravy.BezDph, upravy.Dph, upravy.SDph),
            Vypln(Souhrn_Licence, "Licenční rozšíření APV a DZ celkem", licence.BezDph, licence.Dph, licence.SDph),
            Vypln(Souhrn_Celkem, "CELKEM", celkem.BezDph, celkem.Dph, celkem.SDph),
        });

    private static Table Tabulka(string tblPr, int[] sloupce, IEnumerable<string> radky)
    {
        var mrizka = string.Concat(sloupce.Select(s => $"<w:gridCol w:w=\"{s.ToString(CultureInfo.InvariantCulture)}\"/>"));
        return Prvek<Table>($"<w:tbl>{tblPr}<w:tblGrid>{mrizka}</w:tblGrid>{string.Concat(radky)}</w:tbl>");
    }

    /// <summary>Doplní texty do míst § v pořadí buněk; text se pro XML escapuje.</summary>
    private static string Vypln(string sablona, params string[] texty)
    {
        var casti = sablona.Split('§');
        if (casti.Length - 1 != texty.Length)
        {
            throw new InvalidOperationException($"Šablona tabulky čeká {casti.Length - 1} hodnot, dostala {texty.Length}.");
        }

        var vysledek = new System.Text.StringBuilder(casti[0]);
        for (var i = 0; i < texty.Length; i++)
        {
            vysledek.Append(Esc(texty[i])).Append(casti[i + 1]);
        }

        return vysledek.ToString();
    }
}
